package dev.chungjungsoo.gptmobile.data.voice

import android.system.Os
import java.nio.file.Files
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE)
class PlainPlatformOsWarmupTest {
    @Test fun initializesTheDefaultPlatformOsBeforeTheScopedBoundary() {
        val parent = Files.createTempDirectory("platform-os-before-voice")
        val child = parent.resolve("prepared")
        try {
            Os.mkdir(child.toString(), 0x1C0)
            assertTrue(Files.isDirectory(child))
        } finally {
            Files.deleteIfExists(child)
            Files.deleteIfExists(parent)
        }
    }
}

